// GEN_SS2F_SuperSmoother2Pole.c  (GENERATED by analysis/harness/generator.py from the spec; edit the spec, not this file)
//
// PURPOSE:  Batch harness SS2F. Feeds synthetic inputs through SuperSmoother2Pole (8 variants:
//           P10, P14, P20, P30, NCA [control], NCB [control], NC1 [control], NC2 [control]) and writes the RAW outputs. It does NOT judge anything.
//           Python (analysis/harness/checker.py) measures and writes PASS/FAIL.
// PREREG:   analysis/harness/specs/SS2_ArticleFidelity.toml (this file)
// INPUTS:   Synthetic only, from the bar counter n: flat | level+amp*sin(2*pi*n/T), T=5,10,20,40,100 | ramp level+slope*n
//           level=11/10 amp=1/100 slope=1/10000. (b, H1 run 1) Decimal literals are float32 in this Zorro
//           build and the PI macro is 3.14159, so every constant is built at run time from integers.
//           EUR/USD is used only as a bar clock; clock_close is exported for the checker's magnitude guard.
// OUTPUT:   Data/GEN_SS2F_raw.csv  (3000 rows n=0..2999 + header; 65 columns; values printed with 15 decimals)
// CALLS:    56 filter calls per bar, variant-major, unconditional, fixed order (gotchas 3.1).
// FEEDING:  every x[n], n=0..2999, reaches the filters exactly once; INITRUN and EXITRUN feed and write nothing.
// NO LOOKBACK GUARD: LookBack = 0, warmup bars are exported too; the checker requires n = 0..2999 contiguous.
// SOURCES:  expected values and tolerances are in the spec, each with an (a)/(b)/(c) label.
//           Pattern copied from strategies/tests/H1_SuperSmoother2Pole_Harness.c (b: H1 run 2 PASS).
// Y[] index = variant*7 + input.

#include <default.c>
#include "../../indicators/ehlers/SuperSmoother2Pole.c"

#define SS2F_RAW "Data/GEN_SS2F_raw.csv"
#define SS2F_MARK "Data/GEN_SS2F_exit_marker.txt"
#define SS2F_NBARS 3000

static int ss2f_n = 0;
static int ss2f_done = 0;
static int ss2f_hdr = 0;
static int ss2f_rows = 0;

// NC-A: realistic copying error (D2 rule 4). Identical to SuperSmoother2Pole.c except c1 gets +1 in
// its 3rd significant digit BEFORE b1, c3, c0 are derived (0.8008 -> 0.8018 at P = 20), so DC gain stays 1.
// The step 1/1000 equals reference.bump3(c1) at P = 20 (b: c1 = 0.800800, magnitude 1e-1 -> step 1e-3).
// Computed from integers at run time, no decimal literal (gotchas 9d.1). Defined here only.
var ss2f_nc_a(vars Price, int P)
{
	var c1 = exp(-sqrt(2.0) * PI / P);
	c1 = c1 + 1.0 / 1000;
	var b1 = 2.0 * c1 * cos(sqrt(2.0) * PI / P);
	var c2 = b1;
	var c3 = -c1 * c1;
	var c0 = (1.0 - b1 + c1 * c1) / 2.0;
	var* Filt = series(Price[0], 3);
	if(Init) {
		Filt[0] = Price[0];
		return Filt[0];
	}
	Filt[0] = c0 * (Price[0] + Price[1]) + c2 * Filt[1] + c3 * Filt[2];
	return Filt[0];
}

// NC-B: realistic copying error (D2 rule 4). Identical to SuperSmoother2Pole.c except c0 gets +1 in
// its 3rd significant digit AFTER all coefficients are computed (0.039518 -> 0.039618 at P = 20); both input
// taps use c0, so DC gain != 1 and the FLAT check must fire (only control that exercises the flat guard).
// The step 1/10000 equals reference.bump3(c0) at P = 20 (b: magnitude 1e-2 -> step 1e-4). Defined here only.
var ss2f_nc_b(vars Price, int P)
{
	var c1 = exp(-sqrt(2.0) * PI / P);
	var b1 = 2.0 * c1 * cos(sqrt(2.0) * PI / P);
	var c2 = b1;
	var c3 = -c1 * c1;
	var c0 = (1.0 - b1 + c1 * c1) / 2.0;
	c0 = c0 + 1.0 / 10000;
	var* Filt = series(Price[0], 3);
	if(Init) {
		Filt[0] = Price[0];
		return Filt[0];
	}
	Filt[0] = c0 * (Price[0] + Price[1]) + c2 * Filt[1] + c3 * Filt[2];
	return Filt[0];
}

// NC2: gross units bug (gotchas §2), H1's NC2 unchanged except the function name. Identical to
// SuperSmoother2Pole.c except the cos argument is in degrees (sqrt(2)*180/P). Defined here only.
var ss2f_ss_deg(vars Price, int P)
{
	var c1 = exp(-sqrt(2.0) * PI / P);
	var b1 = 2.0 * c1 * cos(sqrt(2.0) * 180.0 / P);
	var c2 = b1;
	var c3 = -c1 * c1;
	var c0 = (1.0 - b1 + c1 * c1) / 2.0;
	var* Filt = series(Price[0], 3);
	if(Init) {
		Filt[0] = Price[0];
		return Filt[0];
	}
	Filt[0] = c0 * (Price[0] + Price[1]) + c2 * Filt[1] + c3 * Filt[2];
	return Filt[0];
}

void run()
{
	// Settings must be assigned on every call, including INITRUN, or Zorro never sees them.
	BarPeriod = 1440;
	StartDate = 20080101;
	EndDate   = 20240101;
	LookBack  = 0;
	asset("EUR/USD");

	if(is(INITRUN)) {
		ss2f_n = 0; ss2f_done = 0; ss2f_hdr = 0; ss2f_rows = 0;	// declared initialisers
		file_delete(SS2F_RAW);
		file_delete(SS2F_MARK);
		return;
	}
	if(is(EXITRUN)) {
		printf("\nSS2F EXIT: rows written = %d, done = %d  (expected 3000 and 1)", ss2f_rows, ss2f_done);
		// marker file: if it exists after the run, EXITRUN ran even if the printf was lost (gotchas 9d.4)
		file_append(SS2F_MARK, strf("EXITRUN ran: rows=%d done=%d\n", ss2f_rows, ss2f_done), 0);
		return;
	}

	int n;
	var X[7];
	var Y[56];
	n = ss2f_n;

	// --- constants built at RUN TIME from integers (gotchas 9d.1, 9d.2) ---
	var lvl = 11;	lvl = lvl / 10;
	var amp = 1;	amp = amp / 100;
	var slp = 1;	slp = slp / 10000;
	var pi_x = 4;	pi_x = pi_x * atan(1);

	// --- inputs from the bar counter (radians); no decimal literal, no PI macro ---
	X[0] = lvl;
	X[1] = lvl + amp * sin(2 * pi_x * n / 5);
	X[2] = lvl + amp * sin(2 * pi_x * n / 10);
	X[3] = lvl + amp * sin(2 * pi_x * n / 20);
	X[4] = lvl + amp * sin(2 * pi_x * n / 40);
	X[5] = lvl + amp * sin(2 * pi_x * n / 100);
	X[6] = lvl + slp * n;

	// --- input series: 7 unconditional calls, fixed order ---
	vars S0 = series(X[0], 3);
	vars S1 = series(X[1], 3);
	vars S2 = series(X[2], 3);
	vars S3 = series(X[3], 3);
	vars S4 = series(X[4], 3);
	vars S5 = series(X[5], 3);
	vars S6 = series(X[6], 3);

	// --- 56 filter calls, variant-major, unconditional, fixed order ---
	Y[0] = SuperSmoother2Pole(S0, 10);	// P10 flat
	Y[1] = SuperSmoother2Pole(S1, 10);	// P10 s5
	Y[2] = SuperSmoother2Pole(S2, 10);	// P10 s10
	Y[3] = SuperSmoother2Pole(S3, 10);	// P10 s20
	Y[4] = SuperSmoother2Pole(S4, 10);	// P10 s40
	Y[5] = SuperSmoother2Pole(S5, 10);	// P10 s100
	Y[6] = SuperSmoother2Pole(S6, 10);	// P10 ramp
	Y[7] = SuperSmoother2Pole(S0, 14);	// P14 flat
	Y[8] = SuperSmoother2Pole(S1, 14);	// P14 s5
	Y[9] = SuperSmoother2Pole(S2, 14);	// P14 s10
	Y[10] = SuperSmoother2Pole(S3, 14);	// P14 s20
	Y[11] = SuperSmoother2Pole(S4, 14);	// P14 s40
	Y[12] = SuperSmoother2Pole(S5, 14);	// P14 s100
	Y[13] = SuperSmoother2Pole(S6, 14);	// P14 ramp
	Y[14] = SuperSmoother2Pole(S0, 20);	// P20 flat
	Y[15] = SuperSmoother2Pole(S1, 20);	// P20 s5
	Y[16] = SuperSmoother2Pole(S2, 20);	// P20 s10
	Y[17] = SuperSmoother2Pole(S3, 20);	// P20 s20
	Y[18] = SuperSmoother2Pole(S4, 20);	// P20 s40
	Y[19] = SuperSmoother2Pole(S5, 20);	// P20 s100
	Y[20] = SuperSmoother2Pole(S6, 20);	// P20 ramp
	Y[21] = SuperSmoother2Pole(S0, 30);	// P30 flat
	Y[22] = SuperSmoother2Pole(S1, 30);	// P30 s5
	Y[23] = SuperSmoother2Pole(S2, 30);	// P30 s10
	Y[24] = SuperSmoother2Pole(S3, 30);	// P30 s20
	Y[25] = SuperSmoother2Pole(S4, 30);	// P30 s40
	Y[26] = SuperSmoother2Pole(S5, 30);	// P30 s100
	Y[27] = SuperSmoother2Pole(S6, 30);	// P30 ramp
	Y[28] = ss2f_nc_a(S0, 20);	// NCA flat
	Y[29] = ss2f_nc_a(S1, 20);	// NCA s5
	Y[30] = ss2f_nc_a(S2, 20);	// NCA s10
	Y[31] = ss2f_nc_a(S3, 20);	// NCA s20
	Y[32] = ss2f_nc_a(S4, 20);	// NCA s40
	Y[33] = ss2f_nc_a(S5, 20);	// NCA s100
	Y[34] = ss2f_nc_a(S6, 20);	// NCA ramp
	Y[35] = ss2f_nc_b(S0, 20);	// NCB flat
	Y[36] = ss2f_nc_b(S1, 20);	// NCB s5
	Y[37] = ss2f_nc_b(S2, 20);	// NCB s10
	Y[38] = ss2f_nc_b(S3, 20);	// NCB s20
	Y[39] = ss2f_nc_b(S4, 20);	// NCB s40
	Y[40] = ss2f_nc_b(S5, 20);	// NCB s100
	Y[41] = ss2f_nc_b(S6, 20);	// NCB ramp
	Y[42] = SuperSmoother2Pole(S0, 21);	// NC1 flat
	Y[43] = SuperSmoother2Pole(S1, 21);	// NC1 s5
	Y[44] = SuperSmoother2Pole(S2, 21);	// NC1 s10
	Y[45] = SuperSmoother2Pole(S3, 21);	// NC1 s20
	Y[46] = SuperSmoother2Pole(S4, 21);	// NC1 s40
	Y[47] = SuperSmoother2Pole(S5, 21);	// NC1 s100
	Y[48] = SuperSmoother2Pole(S6, 21);	// NC1 ramp
	Y[49] = ss2f_ss_deg(S0, 20);	// NC2 flat
	Y[50] = ss2f_ss_deg(S1, 20);	// NC2 s5
	Y[51] = ss2f_ss_deg(S2, 20);	// NC2 s10
	Y[52] = ss2f_ss_deg(S3, 20);	// NC2 s20
	Y[53] = ss2f_ss_deg(S4, 20);	// NC2 s40
	Y[54] = ss2f_ss_deg(S5, 20);	// NC2 s100
	Y[55] = ss2f_ss_deg(S6, 20);	// NC2 ramp

	// --- write one row per fed bar ---
	if(!ss2f_done) {
		if(!ss2f_hdr) {
			file_append(SS2F_RAW, "n,clock_close,x_flat,x_s5,x_s10,x_s20,x_s40,x_s100,x_ramp", 0);
			file_append(SS2F_RAW, ",y_P10_flat,y_P10_s5,y_P10_s10,y_P10_s20,y_P10_s40,y_P10_s100,y_P10_ramp", 0);
			file_append(SS2F_RAW, ",y_P14_flat,y_P14_s5,y_P14_s10,y_P14_s20,y_P14_s40,y_P14_s100,y_P14_ramp", 0);
			file_append(SS2F_RAW, ",y_P20_flat,y_P20_s5,y_P20_s10,y_P20_s20,y_P20_s40,y_P20_s100,y_P20_ramp", 0);
			file_append(SS2F_RAW, ",y_P30_flat,y_P30_s5,y_P30_s10,y_P30_s20,y_P30_s40,y_P30_s100,y_P30_ramp", 0);
			file_append(SS2F_RAW, ",y_NCA_flat,y_NCA_s5,y_NCA_s10,y_NCA_s20,y_NCA_s40,y_NCA_s100,y_NCA_ramp", 0);
			file_append(SS2F_RAW, ",y_NCB_flat,y_NCB_s5,y_NCB_s10,y_NCB_s20,y_NCB_s40,y_NCB_s100,y_NCB_ramp", 0);
			file_append(SS2F_RAW, ",y_NC1_flat,y_NC1_s5,y_NC1_s10,y_NC1_s20,y_NC1_s40,y_NC1_s100,y_NC1_ramp", 0);
			file_append(SS2F_RAW, ",y_NC2_flat,y_NC2_s5,y_NC2_s10,y_NC2_s20,y_NC2_s40,y_NC2_s100,y_NC2_ramp", 0);
			file_append(SS2F_RAW, "\n", 0);
			ss2f_hdr = 1;
		}
		file_append(SS2F_RAW, strf("%d,%.15f,%.15f,%.15f,%.15f,%.15f,%.15f,%.15f,%.15f", n, priceClose(), X[0], X[1], X[2], X[3], X[4], X[5], X[6]), 0);
		file_append(SS2F_RAW, strf(",%.15f,%.15f,%.15f,%.15f,%.15f,%.15f,%.15f", Y[0],Y[1],Y[2],Y[3],Y[4],Y[5],Y[6]), 0);
		file_append(SS2F_RAW, strf(",%.15f,%.15f,%.15f,%.15f,%.15f,%.15f,%.15f", Y[7],Y[8],Y[9],Y[10],Y[11],Y[12],Y[13]), 0);
		file_append(SS2F_RAW, strf(",%.15f,%.15f,%.15f,%.15f,%.15f,%.15f,%.15f", Y[14],Y[15],Y[16],Y[17],Y[18],Y[19],Y[20]), 0);
		file_append(SS2F_RAW, strf(",%.15f,%.15f,%.15f,%.15f,%.15f,%.15f,%.15f", Y[21],Y[22],Y[23],Y[24],Y[25],Y[26],Y[27]), 0);
		file_append(SS2F_RAW, strf(",%.15f,%.15f,%.15f,%.15f,%.15f,%.15f,%.15f", Y[28],Y[29],Y[30],Y[31],Y[32],Y[33],Y[34]), 0);
		file_append(SS2F_RAW, strf(",%.15f,%.15f,%.15f,%.15f,%.15f,%.15f,%.15f", Y[35],Y[36],Y[37],Y[38],Y[39],Y[40],Y[41]), 0);
		file_append(SS2F_RAW, strf(",%.15f,%.15f,%.15f,%.15f,%.15f,%.15f,%.15f", Y[42],Y[43],Y[44],Y[45],Y[46],Y[47],Y[48]), 0);
		file_append(SS2F_RAW, strf(",%.15f,%.15f,%.15f,%.15f,%.15f,%.15f,%.15f", Y[49],Y[50],Y[51],Y[52],Y[53],Y[54],Y[55]), 0);
		file_append(SS2F_RAW, "\n", 0);
		ss2f_rows += 1;
		if(n == SS2F_NBARS - 1) {
			ss2f_done = 1;	// latch first; nothing is written after this row
			quit("SS2F batch complete: 3000 rows written");
		} else {
			ss2f_n += 1;
		}
	}
}
